"""Publish a self-contained report with actual scenarios, stock layers and retained document links."""
import html,json,shutil
from pathlib import Path
from datetime import datetime
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'outputs/warehouse-control'
def main():
 state=json.loads((OUT/'manifest.json').read_text('utf-8'));ui=json.loads((OUT/'browser-check.json').read_text('utf-8'));queries=json.loads((OUT/'query-check.json').read_text('utf-8'));tests=json.loads((OUT/'regression.json').read_text('utf-8'))
 assert len(state['results'])==28 and state['protected_baseline_unchanged'] and ui['result']==queries['result']=='PASS'
 def esc(v):return html.escape(str(v))
 def table(headers,rows):return '<table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
 def link(kind,id,label):return '<a href="/oms-supplychain/'+('warehouseTransfers' if kind=='transfer' else 'warehouseReconciliation')+'?id='+str(id)+'">'+esc(label)+'</a>'
 def stock(label,s):return [esc(label)]+[s.get(k,'—') for k in ['total','transit','owned','available','allocated','reserved','frozen']]
 css="""body{margin:0;background:#f3f6fb;color:#34445b;font:15px/1.8 'Microsoft YaHei',sans-serif}main{max-width:1420px;margin:28px auto;background:white;padding:32px;border-radius:10px}h1{font-size:27px}h2{font-size:21px;margin-top:32px}h3{font-size:17px}.muted{color:#7a899d;font-size:13px}.metrics{display:flex;gap:14px;flex-wrap:wrap}.metrics article{flex:1;min-width:170px;background:#eef5fd;border-radius:8px;padding:18px}.metrics span,.metrics b{display:block}.metrics b{font-size:25px;color:#278558}table{border-collapse:collapse;width:100%;font-size:13px;margin:15px 0}th,td{padding:11px;border:1px solid #dfe7f0;text-align:left;overflow-wrap:anywhere}th{background:#f4f7fb}section{margin-top:28px;border-top:2px solid #edf2f8;padding-top:12px}a{color:#0877dc;overflow-wrap:anywhere}.pass{color:#278558;font-weight:600}.notice{padding:18px;background:#fff8e9;border-radius:7px}pre{font-size:12px;background:#f4f7fb;white-space:pre-wrap;overflow-wrap:anywhere;padding:16px}img{display:block;max-width:100%;border:1px solid #dfe7f0;margin-top:12px}figure{margin:28px 0}figcaption{font-weight:600}summary{cursor:pointer;color:#0877dc}details{margin:14px 0}"""
 parts=['<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>库存对账与跨仓调拨验收报告</title><style>'+css+'</style><main><h1>库存对账与跨实仓调拨 · 验收报告</h1><p class="muted">'+datetime.now().isoformat()+' · 本地TEST奇门仓库 · 单据和数据保留</p><div class="metrics">']
 for name,value in [('后端相关回归',str(tests['total_tests'])+' 项通过'),('详细业务场景','28 项通过'),('页面验收',str(len(ui['checks']))+' 项通过'),('查询及库存检查',str(len(queries['checks']))+' 项通过')]:parts.append('<article><span>'+name+'</span><b>'+value+'</b></article>')
 parts.append('</div><p><a href="/oms-supplychain/warehouseTransfers">跨仓调拨</a>　<a href="/oms-supplychain/warehouseReconciliation">库存对账</a>　<a href="/oms-inventory/productInventory">商品库存</a>　<a href="/oms-supplychain/operations">供应链待办</a></p><h2>交付范围与口径</h2><p>库存对账按公司、货主、实仓、SKU、批次、质量比较，同一货主同一实仓下全部虚仓先合计，再与仓库库存比较一次。WMS实物=未冻结数量+冻结数量。OMS业务占用和WMS冻结分别核查；缺失字段、缺失SKU、缺失批次、未完成分页和查询失败都不当作零库存。</p><p>对账保存双边快照时间、具体差额、虚仓来源及待确认单据。存在待入账、冻结待核查或缺失字段时不开放实物调整。真实盘盈盘亏通过独立TZ申请、明确虚仓与原成本及盘点证据，审核后后台按差量入账；库存版本变化会阻止旧快照调整。同范围更新成功快照保留旧证据，并替代过期待办。</p><p>调拨限同公司、同货主、不同实仓，保留原批次、质量、库存单位及成本。明确审核后，库存占用、调出下发、实际出库、调入下发、实收入账自动运行。原仓最终确认后，目的仓按原实际出库数量下发；中间出库保留原剩余占用。停止仅释放未出库部分；已出库退回原仓须建立独立DBH收回入库并按实际收到数量恢复。</p><p><b>公司拥有=仓库实物+调拨在途。</b>原仓发10、目的收8：原仓实物减少10，目的增加8，在途2。公司仓库实物比原来少2，但拥有量不变。在途不计可用、不计渠道可售。原正次品分别结算，次品继续不可售。</p><p>调拨执行与仓库对账查询使用两个独立有界线程池，每池2线程、128等待槽；扫描只提交到期任务。任务、租约、增量幂等事件和退避保存在数据库；同SKU先取库存互斥，再读取锁内最新余额。库存RPC不持供应链业务行锁。当前页批量汇总，不逐行调用仓库。自动执行不使用sleep等待。</p><p>协议按<a href="https://developer.alibaba.com/docs/doc.htm?articleId=118403&amp;docType=1&amp;treeId=285">奇门官方白皮书</a>5.7—5.8、5.13—5.15、5.32、5.34—5.35、5.38核对：DBCK stockout、DBRK entryorder、order.cancel、inventory.query、stock.query、inventory.report。盘点通知的quantity为有符号变化量，仅保存验签证据，不自动调账。</p><div class="notice">采购、调拨和差异调整的审核、停止及收回安排属于明确的人工业务决策；决策后各项库存和仓库步骤由后台自动执行。测试没有用SQL改写目标业务状态或库存代替流程。WMS事实来自本地TEST模拟器与签名回传，真实仓库仍需联调。没有绑定或写入真实店铺；已验证渠道可售计算及库存信号；库存信号唤醒待分仓订单，店铺同步由现有任务在下一轮读取最新库存。目标仓须同时位于渠道范围和店铺允许仓内才计入可售。</div>')
 parts.append('<h2>保留单据索引</h2>'+table(['场景','详细说明','保留单据','结果'],[[r['key'],'<a href="#case-'+r['key']+'">'+esc(r['title'])+'</a>',link('transfer',r['transfer_id'],'查看调拨') if r.get('transfer_id') else link('reconciliation',r['evidence']['reconciliation']['id'],'查看对账') if isinstance(r.get('evidence'),dict) and r['evidence'].get('reconciliation') else '详见场景证据','<span class="pass">通过</span>'] for r in state['results']]))
 parts.append('<h2>全部场景完成后的库存</h2>'+table(['SKU','仓库实物','在途','公司拥有','可用','已分配','预占','不可售/冻结'],[stock(s['sku'],s) for s in state['final_stock'].values()]))
 parts.append('<div class="notice">特意保留 '+link('transfer',state['transit_transfer_id'],'2件真实在途测试单')+' 供验收：公司拥有10件、仓库实物8件、调拨在途2件、可用8件。另保留 '+link('transfer',state['draft_transfer_id'],'未审核草稿')+'，以及缺失、冻结、并发占用失败等负向场景。它们的未完成状态符合各自测试预期。</div>')
 for r in state['results']:
  parts.append('<section id="case-'+r['key']+'"><h2>'+r['key']+' '+esc(r['title'])+' <span class="pass">通过</span></h2><p>'+esc(r['scenario'])+'</p>')
  if r.get('transfer_id'):parts.append('<p>'+link('transfer',r['transfer_id'],'查看原调拨业务单')+'</p>')
  if r.get('before_stock') and r.get('after_stock'):
   parts.append(table(['阶段','仓库实物','在途','公司拥有','可用','已分配','预占','不可售/冻结'],[stock('该步骤前',r['before_stock']),stock('该步骤后',r['after_stock'])]));parts.append('<details><summary>仓库及批次数量核对</summary><p class="muted">每行：虚仓、正品实物、次品实物、正品可用、次品可用、正品锁定、次品锁定。已逐SKU验证仓库与批次一致。</p><pre>'+esc(r['after_stock']['warehouses'])+'</pre></details>')
  parts.append('<details><summary>查看完整单据、仓库回传、快照及库存证据</summary><pre>'+esc(json.dumps(r['evidence'],ensure_ascii=False,indent=2))+'</pre></details></section>')
 parts.append('<h2>回归中发现并修复的问题</h2><ul><li>收货与原仓收回并发时，旧代码在加锁前读取余额，可能同时消耗一份在途。已改为先按SKU和调拨单加锁，再重读原行余额；并发真实事务回归确认只能一个超出共同余额的请求成功。</li><li>盘点通知消息编号曾误按数字解析，导致合法签名通知被拒绝。已按字符串身份处理，补齐真实验签回调、重复消息与冲突消息回归；-2通知仅留证、不重复盘亏。</li><li>停止流程增加取消后待入账事件复核，收到新的实物回传时先入账再释放。零出库的未下发目的单明确结束，等待回传的已接单任务不被高频扫描。</li><li>商品库存补充分开的实物、在途、拥有数量及调拨来源；对账检查完成与库存调整入账分别表达，仓库动作使用中文名称。</li><li>渠道可售同时受渠道库存范围和店铺允许仓限制；调入不在渠道范围内的目的仓后，不会直接放大该渠道可售。</li></ul><h2>浏览器验收</h2><ol>'+''.join('<li>'+esc(c)+'</li>' for c in ui['checks'])+'</ol>')
 captions={'01-transfer-full.png':'完整调拨与双侧仓库执行','02-transfer-consecutive-recovery.png':'最终短收及连续独立收回','03-transfer-partial-stop.png':'部分出库停止与剩余释放','04-transfer-mixed-quality.png':'同SKU原批次正次品分行','05-create-transfer-source.png':'新增调拨原批次及当前可调数量','06-reconciliation-aggregate.png':'多虚仓聚合及双边快照','07-reconciliation-loss-reviewed.png':'明确盘亏差额与独立审核入账','08-reconciliation-pending.png':'待确认单据及差额暂不调整','09-reconciliation-missing.png':'缺失库存不按零处理','10-reconciliation-frozen.png':'实物一致与冻结来源分开核查','11-inventory-report.png':'盘点变化量与盘点总量分开','12-supplychain-operations.png':'统一供应链待办','13-inventory-transit-owned.png':'商品库存直接显示实物、在途及拥有数量'}
 for f,title in captions.items():assert (OUT/f).is_file(),f;parts.append('<figure><figcaption>'+title+'</figcaption><a href="'+f+'"><img src="'+f+'" alt="'+title+'"></a></figure>')
 parts.append('<h2>查询、库存和性能检查</h2><ol>'+''.join('<li>'+esc(c)+'</li>' for c in queries['checks'])+'</ol>'+table(['入口','读取样本','中位耗时毫秒','最小 / 最大毫秒'],[[esc(t['endpoint']),len(t['samples_ms']),t['median_ms'],str(min(t['samples_ms']))+' / '+str(max(t['samples_ms']))] for t in queries['timings']])+'<p class="muted">本地连续5次读取只用于观察查询退化，不代表生产容量测试。全部读取前后仓库交互数量未增加。11张新增表的所有字段均有中文备注。</p><details><summary>查询计划</summary><pre>'+esc(json.dumps(queries['explain'],ensure_ascii=False,indent=2))+'</pre></details><h2>原始库存流水</h2>')
 for sku,ledger in queries['ledger'].items():parts.append('<details><summary>'+esc(sku)+'</summary><pre>'+esc(ledger)+'</pre></details>')
 parts.append('<p class="notice">原订单、退款、换货、采购、相关库存、自动任务及队列策略基线全部核对一致。测试采购、调拨、调整、仓库交互和库存流水均保留。</p></main></html>')
 (OUT/'验收报告.html').write_text(''.join(parts),'utf-8');dest=ROOT/'docker/local/dist/acceptance/warehouse-control';dest.mkdir(parents=True,exist_ok=True)
 for f in OUT.iterdir():
  if f.is_file() and f.suffix in ['.html','.json','.png']:shutil.copy2(f,dest/f.name)
 print('Report published: http://127.0.0.1:8088/acceptance/warehouse-control/验收报告.html')
if __name__=='__main__':main()
